WITH recent_subscriptions AS (SELECT *, DATEDIFF(CURRENT_DATE(), end_date) AS days_since_end_date FROM subscriptions WHERE MONTH(start_date) IN (3, 4, 8) AND monthly_fee BETWEEN 100 AND 120), Summary AS (SELECT DATE_FORMAT(start_date, 'yyyy-MM') AS start_month, plan, MAX(days_since_end_date) - MIN(days_since_end_date) AS days_since_end_date_range FROM recent_subscriptions GROUP BY DATE_FORMAT(start_date, 'yyyy-MM'), plan) SELECT start_month, days_since_end_date_range FROM Summary WHERE days_since_end_date_range >= 63 ORDER BY start_month ASC, days_since_end_date_range ASC;
